window.ScripturaLexicons.BDAG_PART_0181 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0181-01\" data-source=\"BDAG\" data-search=\"καθαρῶς advérbio puramente; em pureza BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθαρῶς</td><td>advérbio</td><td>puramente; em pureza</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0181-02\" data-source=\"BDAG\" data-search=\"καθέδρα, ας, ἡ substantivo feminino cadeira; assento; cadeira de mestre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθέδρα, ας, ἡ</td><td>substantivo feminino</td><td>cadeira; assento; cadeira de mestre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0181-03\" data-source=\"BDAG\" data-search=\"καθέζομαι verbo médio estar sentado; sentar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθέζομαι</td><td>verbo médio</td><td>estar sentado; sentar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0181-04\" data-source=\"BDAG\" data-search=\"καθεῖλον, καθελεῖν, καθελῶ, καθελών remissão morfológica ver καθαιρέω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθεῖλον, καθελεῖν, καθελῶ, καθελών</td><td>remissão morfológica</td><td>ver καθαιρέω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0181-05\" data-source=\"BDAG\" data-search=\"καθεῖς remissão lexical ver εἷς, acepção 5e BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθεῖς</td><td>remissão lexical</td><td>ver εἷς, acepção 5e</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0181-06\" data-source=\"BDAG\" data-search=\"καθεξῆς advérbio em ordem; sucessivamente; ponto por ponto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθεξῆς</td><td>advérbio</td><td>em ordem; sucessivamente; ponto por ponto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0181-07\" data-source=\"BDAG\" data-search=\"καθερίζω remissão ortográfica ver καθαρίζω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθερίζω</td><td>remissão ortográfica</td><td>ver καθαρίζω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0181-08\" data-source=\"BDAG\" data-search=\"καθεύδω verbo dormir; estar espiritualmente indiferente; estar morto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθεύδω</td><td>verbo</td><td>dormir; estar espiritualmente indiferente; estar morto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0181-09\" data-source=\"BDAG\" data-search=\"καθήγησις, εως, ἡ substantivo feminino instrução; orientação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθήγησις, εως, ἡ</td><td>substantivo feminino</td><td>instrução; orientação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0181-10\" data-source=\"BDAG\" data-search=\"καθηγητής, οῦ, ὁ substantivo masculino mestre; professor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθηγητής, οῦ, ὁ</td><td>substantivo masculino</td><td>mestre; professor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0181-11\" data-source=\"BDAG\" data-search=\"καθῆκα remissão morfológica ver καθίημι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθῆκα</td><td>remissão morfológica</td><td>ver καθίημι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0181-12\" data-source=\"BDAG\" data-search=\"καθηκόντως advérbio convenientemente; conforme o dever BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθηκόντως</td><td>advérbio</td><td>convenientemente; conforme o dever</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0181-13\" data-source=\"BDAG\" data-search=\"καθήκω verbo ser apropriado; caber; ser devido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθήκω</td><td>verbo</td><td>ser apropriado; caber; ser devido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0181-14\" data-source=\"BDAG\" data-search=\"καθηλόω verbo prender com pregos; pregar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθηλόω</td><td>verbo</td><td>prender com pregos; pregar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0181-15\" data-source=\"BDAG\" data-search=\"κάθημαι verbo estar sentado; morar; sentar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">κάθημαι</td><td>verbo</td><td>estar sentado; morar; sentar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0181-16\" data-source=\"BDAG\" data-search=\"καθημέραν locução adverbial por dia; ver ἡμέρα BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθημέραν</td><td>locução adverbial</td><td>por dia; ver ἡμέρα</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0181-17\" data-source=\"BDAG\" data-search=\"καθημερινός, ή, όν adjetivo cotidiano; diário BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθημερινός, ή, όν</td><td>adjetivo</td><td>cotidiano; diário</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0181-18\" data-source=\"BDAG\" data-search=\"καθίζω verbo sentar alguém; nomear; sentar-se; residir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθίζω</td><td>verbo</td><td>sentar alguém; nomear; sentar-se; residir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0181-19\" data-source=\"BDAG\" data-search=\"καθίημι verbo fazer descer; baixar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθίημι</td><td>verbo</td><td>fazer descer; baixar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0181-20\" data-source=\"BDAG\" data-search=\"καθιστάνω remissão lexical ver καθίστημι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">καθιστάνω</td><td>remissão lexical</td><td>ver καθίστημι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0181-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθαρῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">advérbio de <span class=\"greek\">καθαρός</span> ( Hesíodo e Hinos Homéricos e posteriores; UPZ 144, 29 [164 b.c. ]; 2 Macc 7:40 variante de leitura ; Philo ; Jos. , Ant. 18, 100 ; Ath. , R. 66, 13 al. ) em pureza, figuradamente Dg 12:3 .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0181-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθέδρα, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( <span class=\"greek\">κατά</span> + <span class=\"greek\">ἕδρα</span> «assento», ver o verbete seguinte; Tucídides e outros ; inscrições e papiros , LXX , En ; Jos. , Ant. 5, 130 ; 19, 100 ; empréstimo vocabular na literatura rabínica ) cadeira, assento (assim em Polyb . 1, 21, 2; Herodian 2, 3, 7; Lucian , Jupp. Tr. 11; BGU 717, 14; LXX ; <span class=\"greek\">κ</span>. <span class=\"greek\">θρόνου</span> En 24:3 ) Hv 1, 2, 2 ; 1, 4, 1 e 3 ; 3, 10, 3 ; 3, 11, 2 e 4 . <span class=\"greek\">καθέδρα</span> <span class=\"greek\">λοιμῶν</span> B 10:10 (conforme Ps 1:1 ). Assento daqueles que vendem alguma coisa (mas ver Dalman , Arbeit VII 192) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:12</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:15</a> ; a cadeira do mestre ( SIG 845, 2f <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">καθέδρας</span> <span class=\"greek\">σοφιστής</span> ) Hm 11:1 ; <span class=\"greek\">ἡ</span> <span class=\"greek\">Μωϋσέως</span> <span class=\"greek\">κ</span> . <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:2</a> ( cf. PJ 23, 1927, 44; ilustração em NAvigad, Chorazin: Enc. of Arch. Excavations in the Holy Land I, 1975, 302; LRahmani, Israel Exploration Journal 40, ’90, 192–214). <span class=\"greek\">κ</span>. <span class=\"greek\">κρίσεως</span> assento do juiz GPt 3:7 ( cf. Ps 106:32 <span class=\"greek\">ἐν</span> <span class=\"greek\">καθέδρᾳ</span> [ <span class=\"greek\">καθέδραις</span> SA] <span class=\"greek\">πρεσβυτέρων</span> ).— B. 482. DELG sob o verbete <span class=\"greek\">ἕζομαι</span> B2. M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0181-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθέζομαι</h1><div class=\"entry-meta\"><span>verbo médio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver <span class=\"greek\">καθέδρα</span> ) imperfeito <span class=\"greek\">ἐκαθεζόμην</span> ; futuro <span class=\"greek\">καθεδοῦμαι</span> e <span class=\"greek\">καθεσθήσομαι</span> , 2ª pessoa do plural <span class=\"greek\">καθεσθήσεσθε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:28</a> variante de leitura (ver <span class=\"greek\">κάθημαι</span> , <span class=\"greek\">καθίζω</span> ); aoristo <span class=\"greek\">ἐκαθέσθην</span> ( TestAbr A 5 p. 81, 31 [Stone p. 10]; AcPl Ha 4, 18); imperativo, 2ª pessoa do singular <span class=\"greek\">καθέσθητι</span> ( TestSol 13:2); infinitivo <span class=\"greek\">καθεσθῆναι</span> ( Just ., D . 83, 1) ( Hom .+). Na literatura aqui considerada, pelo menos predominantemente, significa</p><p class=\"entry-text\">① estar sentado; sentar-se (como em Lísias 13, 37; Epict . 1, 29, 55; 3, 24, 18; Paus . 10, 5, 2; Vett. Val. 78, 24; OGI 201, 13; LXX ; TestSol ; Jos. , Bell. 5, 73 , Ant. 12, 171 ; Just ., D . 90, 5 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">λίθου</span> ) <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἱερῷ</span> referindo-se a mestres <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:55</a>. Referindo-se a alunos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:46</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">συνεδρίῳ</span> no conselho <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:15</a>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">θυρίδος</span> 20:9 ( Ael. Aristid. 47, 23 K.=23 p. 451 D .: <span class=\"greek\">κ</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">βήματος</span> ). <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πύλῃ</span> 3:10 D . <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">οἴκῳ</span> estar sentado, permanecer em casa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:20</a>. Em emprego absoluto, estar sentado ali 20:12. O sentido mais amplo «estar, encontrar-se situado» também é possível em algumas passagens ( Paus . Attic. <span class=\"greek\">ς</span> , 8 <span class=\"greek\">ἐν</span> <span class=\"greek\">νησίῳ</span> <span class=\"greek\">καθεζόμεναι</span> =permanecer; Stephan. Byz. sob o verbete <span class=\"greek\">Σκίρος</span> : <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">τόπῳ</span> <span class=\"greek\">τούτῳ</span> ; Biogr. p. 265; Lev 12:5 ; Jos. , Ant. 6, 32 , Vi. 286 ; Just ., D . 49, 3; 51, 2 al. ).</p><p class=\"entry-text\">② assumir posição sentada, sentar-se ( Hom ., Trag. et al. ; Jos. , Vi. 222 ; SibOr 5, 460 ; TestSol 13:2; 18:24; TestJob 51:3; Just ., D . 107, 3.—O imperfeito com nuance aorística: «sentei-me»; B-D-F § 101 ; ver Rob. 837 ff; 882 f) <span class=\"greek\">ἐκαθέζετο</span> <span class=\"greek\">αὐτὴ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">δεξιῶν</span> ela mesma se sentou à direita Hv 3, 2, 4 . <span class=\"greek\">εἰς</span> <span class=\"greek\">καθέδραν</span> numa cadeira 3, 11, 4. <span class=\"greek\">Ἰησοῦς</span> <span class=\"greek\">ἐκαθέζετο</span> <span class=\"greek\">οὔτως</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πηγῇ</span> Jesus sentou-se, como estava, junto ao poço <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:6</a> (sobre a expressão e o conceito, ver Jos. , Ant. 2, 257 f e Marinus, Vi. Procli 10 Boiss. As early as Demosth . 21, 119 <span class=\"greek\">οὑτωσὶ</span> <span class=\"greek\">καθεζόμενος</span> ). Cf. também 6:3 variante de leitura ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:30</a> D . <span class=\"greek\">ὡς</span> … <span class=\"greek\">ἐκαθέσθη</span> quando (Jerônimo) se sentou AcPl Ha 4, 18f.— DELG sob o verbete <span class=\"greek\">ἕζομαι</span> B2. M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0181-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθεῖλον, καθελεῖν, καθελῶ, καθελών</h1><div class=\"entry-meta\"><span>remissão morfológica</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">ver <span class=\"greek\">καθαιρέω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0181-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθεῖς</h1><div class=\"entry-meta\"><span>remissão lexical</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( <span class=\"greek\">καθ</span>’ <span class=\"greek\">εἷς</span> ) ver <span class=\"greek\">εἷς</span>, acepção 5e.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0181-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθεξῆς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">advérbio menos frequente que os anteriores <span class=\"greek\">ἑξῆς</span> e <span class=\"greek\">ἐφεξῆς</span> ( IGR IV, 1432, 9; Plut ., Mor. 615b; Aelian , VH 8, 7; TestJud 25:1 ; ApcMos 8) relativo à sucessão no tempo, no espaço ou no raciocínio: em ordem, um após o outro, <span class=\"greek\">διερχόμενος</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">Γαλατικὴν</span> <span class=\"greek\">χώραν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Φρυγίαν</span> de um lugar a outro na Galácia e na Frígia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:23</a>. <span class=\"greek\">κ</span>. <span class=\"greek\">τινί</span> (<span class=\"greek\">τι</span>) <span class=\"greek\">γράφειν</span> escrever algo para alguém em sequência ordenada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:3</a> (ver PScheller, De hellenist. historiae conscr. arte, diss. Leipz. 1911, 45, com referência a Polyb . 38, 5 [39, 1]; HConzelmann, Die Mitte der Zeit 3 ’60, tradução inglesa GBuswell ’60 [a teologia domina a estrutura de Lucas]; MVölkel, NTS 20, ’74, 289–99; FMussner, in Jesus und Paulus, WKümmel Festschr. ’75, 253–55; GSchneider, ZNW 68, ’77, 128–31; DMoessner, in The Four Gospels, FNeirynck Festschr. , ed. FvanSegbroeck et al. ’92, II 1065–76; LAlexander, The Preface to Luke’s Gospel ’93, 131f). <span class=\"greek\">ἐκτίθεσθαι</span> <span class=\"greek\">τινι</span> <span class=\"greek\">κ</span> . explicar a alguém ponto por ponto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:4</a>. —Com o artigo <span class=\"greek\">οἱ</span> <span class=\"greek\">κ</span> . os sucessores <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:24</a> ; <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span> . o que vem a seguir: <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κ</span> . no que se segue MPol 22:3 ; depois <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:1</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span> . e assim por diante 1 Cl 37:3 .— DELG sob o verbete <span class=\"greek\">ἑξῆς</span> . M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0181-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθερίζω</h1><div class=\"entry-meta\"><span>remissão ortográfica</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">ver <span class=\"greek\">καθαρίζω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0181-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθεύδω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">imperfeito <span class=\"greek\">ἐκάθευδον</span> ( Hom .+; SIG 1004, 44; BGU 1141, 32; PSI 94, 17; LXX ; TestSol 13:3; Test12Patr ; JosAs ; Philo ; Jos. , Vi. 248 ; Just ., D . 127, 2) imperfeito <span class=\"greek\">ἐκάθευδον</span> .</p><p class=\"entry-text\">① deixar de estar acordado; dormir, literalmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:24</a> ; 13:25 ; 25:5 ; 26:40, 43, 45 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:27</a>, 38 ; 13:36 ; 14:37, 40f ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.46\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:46</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:7</a>. O significado é incerto em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:24</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:39</a> (RKer, ET 65, ’53/54, 315f); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:52</a> ; nessas passagens, a acepção 3 tem encontrado defensores.</p><p class=\"entry-text\">② ser espiritualmente indolente, ser indiferente; extensão figurada da acepção 1 ( cf. X. , An. 1, 3, 11; Enômao em Eus. , PE 5, 19, 2 referindo-se a uma indiferença apática) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:6</a>. —O vocábulo também é empregado figuradamente na citação de um hino desconhecido: <span class=\"greek\">ἔγειρε</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">καθεύδων</span> desperta, ó tu que dormes! <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 5:14</a>.</p><p class=\"entry-text\">③ estar morto, dormir; extensão figurada da acepção 1 ( Ps 87:6 ; Da 12:2 ), expressão eufemística (muito mais frequente nesse sentido é <span class=\"greek\">κοιμάω</span> , ver a acepção 2; sobre o tema, ver BLier, Topica carminum sepulcralium latinorum: Philol 62, 1903, 445–77, 563–603; 63, 1904, 54–65; MOgle, The Sleep of Death: MAAR 11, ’33, 81–117; RLattimore, Themes in Greek and Latin Epitaphs ’62; cf. <span class=\"greek\">εὕδειν</span> Il. 14, 482; Soph ., O.C. 621; Pind . Fgm. 116, 3f [ OxfT ]; ver Schmidt, Syn. I 488f) e assim, segundo a maioria dos estudiosos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:10</a> (THoward, Grace Theological Journal 6, ’85, 337–48; but MLautenschlager, ZNW 80, ’89, 39–59, na acepção 2); ver também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:24</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:39</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:52</a> na acepção 1 acima.— B. 269. DELG sob o verbete <span class=\"greek\">εὕδω</span> . M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0181-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθήγησις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver o verbete seguinte; desde o século I a.C. no sentido de «regra, princípio») provavelmente instrução <span class=\"greek\">μ̣ε̣</span>|<span class=\"greek\">γάλῃ</span> <span class=\"greek\">καθ̣</span>[<span class=\"greek\">ηγήσει</span>] com instrução completa (?) AcPl Ha 6, 31.— DELG sob o verbete <span class=\"greek\">ἡγέομαι</span> .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0181-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθηγητής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver o verbete anterior) mestre, professor (assim em Dionys. Hal., Jud. de Thu . 3, 4; Plut ., Mor. 327f referindo-se a Aristóteles; Vett. Val. 115, 18; IG XIV, Suppl. 2454, 5, um memorial, ver New Docs 4, 156; FX 7, ’81, 64, 3 e p. 158, n. 106 para outras referências; ARaubitschek, Hesperia 35, ’66, 248f, no. 10; PGiss 80, 7; 11; POxy 930, 6; 20) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:10</a>. Este versículo é suprimido por Blass, Wlh. e Dalman (Worte 279; 276) como variante do versículo 8. Neste último, <span class=\"greek\">κ</span> . é variante de leitura — DELG sob o verbete <span class=\"greek\">ἡγέομαι</span> . M-M . Spicq .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0181-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθῆκα</h1><div class=\"entry-meta\"><span>remissão morfológica</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">ver <span class=\"greek\">καθίημι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0181-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθηκόντως</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">advérbio do particípio presente de <span class=\"greek\">καθήκω</span> ( ver o verbete ) convenientemente, de acordo com a obrigação ou dever ( Polyb . 5, 9, 6; Plut ., Mor. 448e; OGI 90, 28 [II b.c. ]; PTebt 793 II, 15 [183 b.c. ]; EpArist 181 ; Philo , Cher. 14 ) 1 Cl 1:3 .— DELG sob o verbete <span class=\"greek\">ἥκω</span> .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0181-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθήκω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">imperfeito, 3ª pessoa do singular <span class=\"greek\">καθῆκεν</span> Jdth 11:13 ( Ésquilo, Heródoto e outros ) ser apropriado, caber a alguém, ser devido ou conveniente <span class=\"greek\">καθήκουσα</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">τιμή</span> o devido respeito 1 Cl 1:3 . Usualmente impessoal <span class=\"greek\">καθήκει</span> cabe (a alguém) ( X. et al. , frequente em inscrições e papiros , LXX ) seguido de acusativo e infinitivo ( Diod S 16, 1, 1; Jos. , Ant. 7, 131 ) <span class=\"greek\">οὐ</span> <span class=\"greek\">καθῆκεν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ζῆν</span> não se deve permitir que ele viva <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 22:22</a> (sobre o imperfeito, ver B-D-F § 358, 2 ; Rob. 886 f).— <span class=\"greek\">τὸ</span> <span class=\"greek\">καθῆκον</span> o que é apropriado, dever ( Menand ., Fgm. 532, 2 Kö.; autores estoicos desde Zenão [ver Ltzm. , Hdb. sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:28</a> ; GNebel, Her 70, ’35, 439–60; MPohlenz, D . Stoa I /II 4th ed. ’70/72: index]; Polyb . 6, 6, 7; papiros e inscrições [sobre a frequência em ambos, ver M-M .]; EpArist 227 ; Philo , Leg. All. 2, 32 a) <span class=\"greek\">πολιτεύεσθαι</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">Χριστῷ</span> conduzir-se de maneira que honre a Cristo ( dativo de vantagem) 1 Cl 3:4 ( cf. IG 2 1365, 15f). <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span> . ( Diog. L. 7, 108; SIG 643, 6 [171 b.c. ]; POxy 1203, 3; Philo , Leg. All. 2, 32 b; Jos. , Ant. 13, 66 ): <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">βουλήσεως</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τι</span> fazer algo contrário ao dever imposto por sua vontade 1 Cl 41:3 . Plural <span class=\"greek\">τὰ</span> <span class=\"greek\">κ</span> . ( X. , Cyr. 1, 2, 5 al. ; EpArist 245 ; Philo , Leg. All. 1, 56 ) <span class=\"greek\">τὰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">καθήκοντα</span> ( UPZ 191, 8 [III b.c. ]; 2 Macc 6:4 ; 3 Macc 4:16 ) <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">καθήκοντα</span> praticar o que não convém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:28</a> (M-JLagrange, Le catalogue des vices dans <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:28</a>–31 , RB 8, 1911, 534–49; contra a hipótese de influência estoica: M-M .).—Sobre a possibilidade de metáfora contratual em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:28</a>, ver Danker, Gingrich Festschr. , ’72, 95f.— B. 643. DELG sob o verbete <span class=\"greek\">ἥκω</span> . M-M . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0181-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθηλόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">1º aoristo <span class=\"greek\">καθήλωσα</span> ; particípio perfeito passivo <span class=\"greek\">καθηλωμένος</span> ( <span class=\"greek\">κατά</span> + <span class=\"greek\">ἧλος</span> «prego»; Polyb . 1, 22, 5; Diod S 20, 85, 2; Hero I 442, 10; Plut ., Alex. 24, 7; SIG 969, 57; 84; PLond IV, 1384, 41; LXX ) prender com pregos, pregar, referente a um condenado a ser queimado numa estaca MPol 14:1 ( cf. Ps.-Callisth . 2, 18, 2 <span class=\"greek\">ἐδέδεντο</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πέδαις</span> <span class=\"greek\">καθηλωταῖς</span> ). Referindo-se a Cristo na cruz: <span class=\"greek\">τὰς</span> <span class=\"greek\">σάρκας</span> B 5:13 ( Ps 118:120 ); ISm 1:2 . Daí, aplicado aos cristãos <span class=\"greek\">ὥσπερ</span> <span class=\"greek\">καθηλωμένοι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">σταυρῷ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χρ</span>. <span class=\"greek\">σαρκί</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πνεύματι</span> como se estivessem pregados à cruz do Senhor Jesus Cristo em corpo e espírito 1:1.— DELG sob o verbete <span class=\"greek\">ἧλος</span> .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0181-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">κάθημαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( Hom .+; ins , pap , LXX , pseudepigr. ; Jos. , Ant. 5, 192 ; Ath. 17:3 [particípio como nome de uma imagem de Atena]) 2ª pessoa singular <span class=\"greek\">κάθῃ</span> (since Hyperid ., Fgm. 115 [OLautensach, Glotta 8, 1917, 186]; POxy 33 verso III, 13 [II a.d. ]; TestJob 24:3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:3</a> ; plural <span class=\"greek\">κάθησθε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:30</a> variante de leitura, imperativo <span class=\"greek\">κάθου</span> ( Moeris 215: <span class=\"greek\">κάθησο</span> <span class=\"greek\">Ἀττικῶς</span>, <span class=\"greek\">κάθου</span> <span class=\"greek\">κοινῶς</span> ; ático posterior [Lautensach, Glotta 9, 1918, 88; ver também AMaidhof, Z . Begriffsbestimmung der Koine 1912, 300]) duas vezes em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:3</a> e sete vezes numa citação de Ps 109:1 ( B-D-F § 100 ; Mlt-H. 206f; ver acepção 3 abaixo); imperfeito <span class=\"greek\">ἐκαθήμην</span> (sobre o aumento, ver B-D-F § 69, 1 ; Mlt-H. 192); futuro <span class=\"greek\">καθήσομαι</span> ( frequentemente na LXX ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:28</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:30</a>.</p><p class=\"entry-text\">① estar em posição sentada, estar sentado</p><p class=\"entry-text\">ⓐ com o lugar indicado por uma preposição <span class=\"greek\">ἀπέναντί</span> <span class=\"greek\">τινος</span> em frente de alguma coisa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.61\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:61</a>. — <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span> sobre alguma coisa ( Pel.-Leg. p. 4, 4 <span class=\"greek\">καθημένη</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">βαδιστήν</span> =«sentado num jumento»; cf. também Musônio 43, 18 H. <span class=\"greek\">καθῆσθαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Σινώπην</span> ) <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄρος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐλαιῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:3</a> ; cf. Hs 5, 1, 1 .— <span class=\"greek\">ἐκ</span> <span class=\"greek\">δεξιῶν</span> <span class=\"greek\">τινος</span> à direita de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.64\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:64</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.62\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:62</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.69\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:69</a>. — <span class=\"greek\">ἐν</span> : <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:16</a> ; 26:69 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:32</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">σάκκῳ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">σποδῷ</span> 10:13. <span class=\"greek\">ἐν</span> <span class=\"greek\">δεξιᾷ</span> <span class=\"greek\">τινος</span> à direita de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.3.1\" target=\"_blank\" rel=\"noopener noreferrer\">Col 3:1</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">δεξιοῖς</span> do lado direito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:5</a>. — <span class=\"greek\">ἐπάνω</span> <span class=\"greek\">τινός</span> sobre alguma coisa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:22</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:8</a>. — <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινος</span> sobre alguma coisa ( Babrius 57, 14; UPZ 79, 10 [160 b.c. ]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:3</a>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θρόνου</span> (Aeschines in Ps. - Demetr . 205; Cebes 21, 3 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">θρόνου</span> <span class=\"greek\">ὑψηλοῦ</span> ; Ex 11:5 al. ; TestAbr A 12 p. 91, 9 [Stone p. 30]; B 8 p. 112, 21 [Stone p. 72]; Jos. , Ant. 5, 192 ); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:2</a> variante de leitura ; 4:9f ; 5:1, 7, 13 variante de leitura ; 6:16 ; 7:10 variante de leitura, 15 ; 19:4 variante de leitura ; 20:11 variante de leitura ; 21:5 variante de leitura <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">θρόνων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:30</a>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">νεφέλης</span> ( Is 19:1 ) 14:15f. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἅρματος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:28</a>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἵππων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:17</a> ; 19:18. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἵππου</span> vs. 19, 21 ( cf. TestJud 3:2 ). Referindo-se a juízes (<span class=\"greek\">κ</span> . = «presidir a um julgamento»: Pla ., Ap. 35c; Hyperid . 3, 6) <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">βήματος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:19</a>. — <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὡραίᾳ</span> <span class=\"greek\">πύλῃ</span> junto à «Porta Formosa» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:10</a>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θρόνῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:13</a> ; 6:16 variante de leitura ; 7:10, 15 variante de leitura ; 19:4 ; 21:5. — <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span> com acusativo de lugar ( Lev 8:35 ) <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τελώνιον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:9</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:14</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:27</a> ; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πῶλον</span> <span class=\"greek\">ὄνου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:15</a> ; <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτόν</span> (cavalo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:2</a>, 4f ; 19:11, 18 variante de leitura ; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">θηρίον</span> 17:3 ; <span class=\"greek\">ἐπὶ</span> (<span class=\"greek\">τὸν</span>) <span class=\"greek\">θρόνον</span>, (<span class=\"greek\">τοὺς</span>) <span class=\"greek\">θρόνους</span> ( 3 Km 1:27 ; Jer 13:13 A; 43, 30 A; TestJob 20:4) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:28</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:2</a>, 4 ; 11:16 ; 20:11 ; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">νεφέλην</span> 14:14, 16 variante de leitura — <span class=\"greek\">παρά</span> <span class=\"greek\">τι</span>, ao lado de alguma coisa <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδόν</span> à beira da estrada <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:30</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:46</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:35</a>. — <span class=\"greek\">περί</span> <span class=\"greek\">τινα</span> ao redor de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:32</a>, 34. — <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> junto ao fogo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.56\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:56</a> ( Aristoph ., Vesp. 773 <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πῦρ</span> <span class=\"greek\">κ</span> . Likewise Menand ., Fgm. 806 Kö.).</p><p class=\"entry-text\">ⓑ com o lugar indicado por advérbio de lugar: <span class=\"greek\">ἐκεῖ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:6</a> ; <span class=\"greek\">οὗ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:2</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:15</a> ; <span class=\"greek\">ὅπου</span> vs. 9.</p><p class=\"entry-text\">ⓒ em emprego absoluto, estar sentado ali ( Epict . 2, 16, 13 <span class=\"greek\">εὔχου</span> <span class=\"greek\">καθήμενος</span> ; 33) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:36</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:17</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:14</a> ; 9:8 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:8</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.30\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:30</a> ; B 10:4 .</p><p class=\"entry-text\">ⓓ com indicação do estado ou das características da pessoa sentada ( Ex 18:14 <span class=\"greek\">σὺ</span> <span class=\"greek\">κάθησαι</span> <span class=\"greek\">μόνος</span> ; <span class=\"greek\">κ</span> . referindo-se a um juiz Ael. Aristid. 46 p. 318 D .; 327) <span class=\"greek\">σὺ</span> <span class=\"greek\">κάθῃ</span> <span class=\"greek\">κρίνων</span> <span class=\"greek\">με</span>; estás aí sentado para julgar-me? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:3</a> ( <span class=\"greek\">Ἄβελ</span> … <span class=\"greek\">κάθηται</span> <span class=\"greek\">ὧδε</span> <span class=\"greek\">κρῖναι</span> TestAbr A 13 p. 92, 7 [Stone p. 32]).</p><p class=\"entry-text\">ⓔ no sentido particular de permanecer sentado tranquilamente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:15</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:35</a>. Estar entronizado em majestade ( Od . 16, 264) <span class=\"greek\">κάθημαι</span> <span class=\"greek\">βασίλισσα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:7</a>.</p><p class=\"entry-text\">② ser residente num lugar; permanecer, estar, morar, estabelecer-se, extensão figurada da acepção 1 ( Hom . et al. ; Hdt. 5, 63 <span class=\"greek\">ἐν</span> <span class=\"greek\">Δελφοῖς</span> ; Musonius p. 59, 7 <span class=\"greek\">ἐν</span> <span class=\"greek\">πόλει</span> ; Ael. Aristid. 50, 14 K.=26 p. 505 D .; Is 9:8 variante de leitura ; 2 Esdr 21 :6; Jdth 4:8 ; 5:3 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:35</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:6</a> ( cf. Jer 32:29); 17:1, 9 (ver acepção 1b). <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> com alguém D 12:3 ; 13:1 . <span class=\"greek\">ἐν</span> <span class=\"greek\">σκότει</span> ( <span class=\"greek\">σκοτίᾳ</span> variante de leitura ) … <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">σκιᾷ</span> <span class=\"greek\">θανάτου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:16</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">σκότει</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σκιᾷ</span> <span class=\"greek\">θανάτου</span> ( Ps 106:10 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.79\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:79</a> ( cf. Pind ., O. 1, 83 <span class=\"greek\">ἐν</span> <span class=\"greek\">σκότῳ</span> <span class=\"greek\">καθήμενος</span> [=aquele que chega à velhice sem realizações dignas de recordação]; Ael. Aristid. 46 p. 272 D .: <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">στενοῖς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐλπίδων</span> <span class=\"greek\">ἐκάθηντο</span> ). (A restituição textual [<span class=\"greek\">καθήμ</span>]<span class=\"greek\">ε̣ν̣ο̣ι̣</span> AcPl Ha 8, 33 é duvidosa; ver a leitura de BMM, sob o verbete <span class=\"greek\">πεδάω</span> .)</p><p class=\"entry-text\">③ assumir posição sentada, sentar-se; a ocorrência desse sentido na literatura aqui considerada dificilmente pode ser contestada, e o mesmo vale para a LXX ( W-S. §14, 3). Deve ser pressuposto para o imperativo em todas as suas ocorrências; sete delas relacionam-se a Ps 109:1: <span class=\"greek\">κάθου</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">δεξιῶν</span> <span class=\"greek\">μου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:44</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:36</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:42</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:34</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:13</a> ; 1 Cl 36:5 ; B 12:10 . O imperativo tem o mesmo significado duas vezes em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:3</a>. Esse sentido também é bastante provável para as seguintes passagens : <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">θαλάσσῃ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:1</a>. <span class=\"greek\">ἐπάνω</span> <span class=\"greek\">τινός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 28:2</a>. <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span> 26:58 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:3</a> ( <span class=\"greek\">καθίζω</span> variante de leitura ). <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">θάλασσαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:1</a>. — <span class=\"greek\">ἐκεῖ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:29</a>. — <span class=\"greek\">μέσος</span> <span class=\"greek\">αὐτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.55\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:55</a>. —Abs. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:2</a>. — B. 455. DELG sob o verbete <span class=\"greek\">ἧμαι</span> . M-M . EDNT . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0181-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθημέραν</h1><div class=\"entry-meta\"><span>locução adverbial</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">em lugar de <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἡμέραν</span> ver <span class=\"greek\">ἡμέρα</span>, acepção 2e.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0181-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθημερινός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">(ver <span class=\"greek\">κατά</span> e <span class=\"greek\">ἡμέρα</span> ; Teofrasto e outros ; Plut ., Lyc. 10, 1, Pyrrh. 14, 12; Polyaenus 4, 2, 10; Alciphron 1, 5, 2; Athen . 6 p. 259f; PTebt 275, 21; PGM 7, 218; Jdth 12:15 ; Jos. , Ant. 3, 238 ; 11, 297 ) de <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἡμέραν</span>: diário, cotidiano <span class=\"greek\">διακονία</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:1</a>. <span class=\"greek\">λόγος</span> a palavra repetida diariamente Hv 1, 3, 2 .— DELG sob o verbete <span class=\"greek\">ἦμαρ</span> . M-M .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0181-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">( Hom . et al. ; ins , pap , LXX ; pseudepigr. ; Joseph .; Just . [apenas em paráfrases]; Tat . 23, 1) futuro <span class=\"greek\">καθίσω</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:31</a> e <span class=\"greek\">καθιῶ</span> Is 47:8 ; 1º aoristo <span class=\"greek\">ἐκάθισα</span> , imperativo <span class=\"greek\">κάθισον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:36</a> variante de leitura ; perfeito, 3ª pessoa do singular <span class=\"greek\">κεκάθικεν</span> ( B-D-F § 101 ; W-S. §14, 2, 15; Rob. 1216 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:2</a>, 1ª pessoa do plural <span class=\"greek\">κεκαθίκαμεν</span> Hs 9, 5, 6 ; futuro médio <span class=\"greek\">καθίσομαι</span> e <span class=\"greek\">καθιοῦμαι</span> Hv 3, 1, 9 .</p><p class=\"entry-text\">① fazer alguém sentar-se, colocar sentado; verbo transitivo <span class=\"greek\">καθίσας</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">δεξιᾷ</span> <span class=\"greek\">αὐτοῦ</span> (Deus) fê-lo sentar-se à sua direita <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:20</a>. Deus jurou a Davi <span class=\"greek\">ἐκ</span> <span class=\"greek\">καρποῦ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὀσφύος</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">καθίσαι</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θρόνον</span> <span class=\"greek\">αὐτοῦ</span> colocar um de seus descendentes sobre o trono <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:30</a> ( cf. 2 Ch 23:20 ). <span class=\"greek\">ἐκάθισαν</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">καθέδραν</span> <span class=\"greek\">κρίσεως</span> fizeram-no sentar-se na cadeira do juiz GPt 3:7 ( <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἐκάθισαν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">βήματος</span> Just ., A I, 35, 6). <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:13</a> provavelmente deve ser entendido nesse sentido, pois o julgamento evidentemente já está em andamento ( cf. Dio Chrys . 4, 67; Loisy; PCorssen, ZNW 15, 1914, 339f; IdelaPotterie, Biblica 41, ’60, 217–47; ver CBQ 25, ’63, 124–26); mas ver também a acepção 3 abaixo. <span class=\"greek\">ἐκάθισέ</span> <span class=\"greek\">με</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἄκρον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὸ̓ρους</span> Hs 9, 1, 4 . Sobre um jumento <span class=\"greek\">ἐκάθισεν</span> <span class=\"greek\">αὐτήν</span> GJs 17:2; <span class=\"greek\">ὄνῳ</span> <span class=\"greek\">καθίσαντες</span> <span class=\"greek\">αὐτόν</span> MPol 8:1 . <span class=\"greek\">ἐκάθισεν</span> <span class=\"greek\">αὐτὴν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τρίτου</span> <span class=\"greek\">βαθμοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θυσιαστηρίου</span> no terceiro degrau do altar GJs 7:3.</p><p class=\"entry-text\">② colocar alguém à frente de alguma coisa; nomear, instalar, autorizar, em uso transitivo, extensão figurada da acepção 1 ( Pla ., Leg. 9, 873e <span class=\"greek\">δικαστήν</span> ; Polyb . 40, 5, 3; Jos. , Ant. 20, 200 <span class=\"greek\">καθίζει</span> <span class=\"greek\">συνέδριον</span> <span class=\"greek\">κριτῶν</span> , Vi. 368 ; POxy 1469, 7) <span class=\"greek\">τοὺς</span> <span class=\"greek\">ἐξουθενημένους</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐκκλησίᾳ</span> <span class=\"greek\">καθίζετε</span>; nomeais juízes pessoas que não têm consideração na igreja? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:4</a> (sobre <span class=\"greek\">καθ</span> . no sentido de «nomear juiz», cf. Jos. , Ant. 13, 75 ).</p><p class=\"entry-text\">③ assumir posição sentada, sentar-se, em uso intransitivo ( Hdt. , Thu ., ins , pap , LXX , pseudepigr. ) em emprego absoluto ( Diod S 8, 10, 4; Polyaenus 2, 21; Just ., A I, 32, 6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:1</a> ; 13:48 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:35</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:20</a> ; 5:3 ; 7:15 variante de leitura ; 14:28, 31 ; 16:6 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:2</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:14</a> ; 16:13 ; Hv 1, 2, 2 . Seguido de infinitivo <span class=\"greek\">ἐκάθισεν</span> <span class=\"greek\">φαγεῖν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:7</a> ( Ex 32:6 ). Com advérbio de lugar <span class=\"greek\">ὧδε</span> ( Sb 4117, 5; Ruth 4:1, 2 ; 4 Km 7:4 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:32</a> ( talvez «permanecei aqui»; Hv 3, 1, 8 ). <span class=\"greek\">αὐτοῦ</span>, aqui ( Gen 22:5 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:36</a>. Com preposição <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ναὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> no templo de Deus ( PSI 502, 21 [III b.c. ] <span class=\"greek\">καθίσαντες</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱερόν</span> ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:4</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">κλίνην</span> sobre o leito ( cf. Dicaearchus , Fgm. 20 W. <span class=\"greek\">εἰς</span> <span class=\"greek\">θρόνον</span> ) Hv 5:1 (sobre sentar-se depois da oração, cf. o preceito pitagórico: Philosoph. Max. 508, 60 <span class=\"greek\">καθῆσθαι</span> <span class=\"greek\">προσκυνήσαντες</span> =depois da oração, devemos sentar-nover Do mesmo modo, Numa: Plut ., Numa 14, 7.—HLewy, Philol . 84, 1929, 378–80). <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">τόπον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀγγέλου</span> Hs 8, 4, 1 . <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔδαφος</span> AcPl Ha 2, 20. <span class=\"greek\">ἐκ</span> <span class=\"greek\">δεξιῶν</span> <span class=\"greek\">τινος</span> à direita de alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:21</a>, 23 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.37\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:37</a>, 40 ; 12:36 variante de leitura ; 16:19 ; Hv 3, 2, 2 . Também <span class=\"greek\">ἐν</span> <span class=\"greek\">δεξιᾷ</span> <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:3</a> ; 8:1 ; 10:12 ; 12:2. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θρόνῳ</span> <span class=\"greek\">μου</span> sobre meu trono <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:21ab</a> ( Hdt. 5, 25 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κατίζων</span> <span class=\"greek\">θρόνῳ</span> ). <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινος</span> ( 3 Km 2:12 al. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">θρόνου</span> ; Diod S 1, 92, 2; 17, 116, 3 <span class=\"greek\">ἐκάθισεν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θρόνου</span> =sentou-se sobre; Jos. , Ant. 8, 344 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:28a</a> ; 25:31 ; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">καθέδρας</span> 23:2 ( B-D-F § 342, 1 ; cf. Rob. 837 ). <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θρόνῳ</span> ( <span class=\"greek\">τοῦ</span> <span class=\"greek\">θ</span> . codd.) GJs 11:1. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span> ( Thu . 1, 126, 10; Aesop , Fab. 393 H. ; AscIs 3:17 ) <span class=\"greek\">θρόνους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 20:4</a> ( cf. 3 Km 1:46 ; 2 Ch 6:10 ); <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">καθέδραν</span> B 10:10 ( Ps 1:1 ); sobre um animal ( TestAbr B 2 p. 106, 25 [Stone p. 60] <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">κτῆνος</span> ; Achilles Tat . 1, 12, 2 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἵππον</span> ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:2</a>, 7 ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:30</a> ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:14</a>. Referindo-se ao Espírito Santo como chama de fogo <span class=\"greek\">ἐκάθισεν</span> <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">ἕνα</span> <span class=\"greek\">ἕκαστον</span> <span class=\"greek\">αὐτῶν</span> pousou sobre cada um deles <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:3</a> ; <span class=\"greek\">κατέναντί</span> <span class=\"greek\">τινος</span> em frente de alguma coisa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.41\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:41</a>. <span class=\"greek\">σύν</span> <span class=\"greek\">τινι</span> sentar-se com alguém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:31</a>. Especialmente referindo-se a um juiz ( Pla ., Leg. 2 p. 659b; Ps 9:5 ) <span class=\"greek\">κ</span>. <span class=\"greek\">ἐπὶ</span> (<span class=\"greek\">τοῦ</span>) <span class=\"greek\">βήματος</span> sentar-se no tribunal para dar início ao julgamento ( Jos. , Bell. 2, 172 <span class=\"greek\">ὁ</span> <span class=\"greek\">Πιλᾶτος</span> <span class=\"greek\">καθίσας</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">βήματος</span> , Ant. 20, 130 ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:13</a> (JBlinzler, Der Prozess Jesu 3 ’60, 257–62; ver 1 above); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:21</a> ; 25:6, 17. —Debaixo de uma árvore GJs 2:4.—Na voz média, sentar-se ( Pla . et al. ; 3 Km 1:13 ; Da 7:26 [ LXX ]; Just ., D . 109, 3 [em lugar de <span class=\"greek\">ἀναπαύσεται</span> Mi 4:4 ]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.19.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 19:28b</a> variante de leitura ; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:3</a> variante de leitura ; ver <span class=\"greek\">καθέζομαι</span> e <span class=\"greek\">κάθημαι</span> .</p><p class=\"entry-text\">④ estar ou permanecer num lugar; uso intransitivo: residir, estabelecer-se, permanecer, viver ( Thu . 3, 107, 1; 4, 93, 1) <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πόλει</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:49</a> ( cf. 1 Ch 19:5 ; 2 Esdr 21 [ Neh 11 ]: 1f; Jos. , Bell. 1, 46 , Ant. 18, 86 ; SIG 685, 28 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἱερῷ</span> ). Com acusativo de tempo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.18.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 18:11</a>. — DELG sob o verbete <span class=\"greek\">ἕζομαι</span> . M-M . EDNT . TW .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0181-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθίημι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">1º aoristo <span class=\"greek\">καθῆκα</span> ( Hom .+; LXX ; TestZeb 6:2 ; Tat . 19, 1 <span class=\"greek\">γένειον</span> … <span class=\"greek\">καθειμένον</span> ostentar «barba comprida») fazer descer <span class=\"greek\">τινά</span>, alguém <span class=\"greek\">διὰ</span> <span class=\"greek\">κεράμων</span> <span class=\"greek\">εἰς</span> ( cp. Jos. , Ant. 2, 31 ; 35 <span class=\"greek\">κ</span> . <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λάκκον</span> ) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:19</a>. <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τείχους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:25</a> (Polyaenus 6, 49 <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">τειχῶν</span> <span class=\"greek\">καθῆκαν</span> ; 8, 21). Voz passiva <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γῆς</span> 10:11 ; <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρανοῦ</span> 11:5. — DELG sob o verbete <span class=\"greek\">ἵημι</span> . M-M .</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0181-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">καθιστάνω</h1><div class=\"entry-meta\"><span>remissão lexical</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\">ver <span class=\"greek\">καθίστημι</span>.</p></section></article>\n"};
